package com.fasterxml.jackson.core.io;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.util.BufferRecycler;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

public class IOContext_releaseBase64Buffer_TriageGen2Test {

    private BufferRecycler _bufferRecycler;
    private IOContext _ioContext;
    private byte[] _testBuffer;

    @Before
    public void setUp() {
        _bufferRecycler = mock(BufferRecycler.class);
        _ioContext = new IOContext(_bufferRecycler, new Object(), true);
        _testBuffer = _ioContext.allocBase64Buffer();
    }

    @Test
    public void testReleaseBase64Buffer_NullBuffer() {
        // Test branch: if (buf != null) is false
        _ioContext.releaseBase64Buffer(null);

        // Verify nothing happened
        verify(_bufferRecycler, never()).releaseByteBuffer(any(), any());
    }

    @Test
    public void testReleaseBase64Buffer_Success() {
        // Test branch: if (buf != null) is true
        // and successful execution path
        _ioContext.releaseBase64Buffer(_testBuffer);

        // Verify buffer was released to recycler with correct codec constant
        verify(_bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, _testBuffer);
    }

    @Test(expected = IllegalStateException.class)
    public void testReleaseBase64Buffer_VerifyReleaseFails() {
        // To test the _verifyRelease logic, we can provide a buffer that wasn't allocated by this context
        // or call it twice. The second call should trigger _verifyRelease failure.

        _ioContext.releaseBase64Buffer(_testBuffer);

        // The first call sets _base64Buffer to null. 
        // The second call will pass a non-null buf, but _base64Buffer is now null.
        // _verifyRelease(buf, null) should throw an exception.
        _ioContext.releaseBase64Buffer(_testBuffer);
    }

    @Test
    public void testReleaseBase64Buffer_WrongBufferReference() {
        // Test that passing a buffer that is not the owned _base64Buffer 
        // triggers the internal verification failure.
        byte[] wrongBuffer = new byte[10];

        try {
            _ioContext.releaseBase64Buffer(wrongBuffer);
        } catch (Exception e) {
            // Assuming _verifyRelease throws an exception when buffers don't match
            // This covers the branch where verification fails.
        }
    }

    @Test
    public void testReleaseBase64Buffer_DoubleReleasePreventsSecondRelease() {
        // Ensure that after the first release, the internal reference is nullified
        // and subsequent calls (if they bypass verify) wouldn't attempt to release the same reference again.

        _ioContext.releaseBase64Buffer(_testBuffer);
        verify(_bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, _testBuffer);

        // If we call it again with the same buffer, it should fail at _verifyRelease 
        // because _base64Buffer was set to null in the first call.
        try {
            _ioContext.releaseBase64Buffer(_testBuffer);
        } catch (Exception e) {
            // Expected
        }
    }
}
